    .reg .u64  %rd_input, %rd_sum, %rd_sum_sq;
    .reg .u32  %rN, %rC, %rH, %rW;
    .reg .u32  %blockIdx_x, %blockIdx_y, %threadIdx_x;
    .reg .u32  %stride, %i, %hw, %h, %w;
    .reg .u64  %addr;
    .reg .f16  %h_val;
    .reg .f32  %f_val, %f_val_sq, %f_sum, %f_sum_sq;
    .reg .pred %p0;

    // -------------------- load parameters --------------------
    ld.param.u64 %rd_input,   [input];
    ld.param.u64 %rd_sum,     [sum];
    ld.param.u64 %rd_sum_sq,  [sum_sq];
    ld.param.u32 %rN,         [N];
    ld.param.u32 %rC,         [C];
    ld.param.u32 %rH,         [H];
    ld.param.u32 %rW,         [W];

    // -------------------- block / thread ids --------------------
    mov.u32 %blockIdx_x, %ctaid.x;
    mov.u32 %blockIdx_y, %ctaid.y;
    mov.u32 %threadIdx_x, %tid.x;

    // total HW per channel
    mul.lo.u32 %hw, %rH, %rW;
    mov.u32 %stride, %ntid.x;

    // init local accumulators
    mov.f32 %f_sum,    0.0;
    mov.f32 %f_sum_sq, 0.0;

    // i = threadIdx.x
    mov.u32 %i, %threadIdx_x;
LOOP_REDUCE:
    setp.ge.u32 %p0, %i, %hw;
    @%p0 bra END_REDUCE;

    // h = i / W ; w = i % W
    div.u32 %h, %i, %rW;
    mul.lo.u32 %addr, %h, %rW;
    sub.u32 %w, %i, %addr;          // w = i - h*W

    // linear index = (( (n*C + c) * H) + h) * W + w
    // n*C
    mul.lo.u32 %addr, %blockIdx_x, %rC;
    // +c
    add.u32 %addr, %addr, %blockIdx_y;
    // *H
    mul.lo.u32 %addr, %addr, %rH;
    // +h
    add.u32 %addr, %addr, %h;
    // *W
    mul.lo.u32 %addr, %addr, %rW;
    // +w
    add.u32 %addr, %addr, %w;

    // byte offset (half = 2 bytes)
    mul.lo.u64 %addr, %addr, 2;
    add.u64 %addr, %rd_input, %addr;

    // load half, convert to float
    ld.global.u16 %h_val, [%addr];
    cvt.f32.f16 %f_val, %h_val;

    // accumulate
    add.f32 %f_sum, %f_sum, %f_val;
    mul.f32 %f_val_sq, %f_val, %f_val;
    add.f32 %f_sum_sq, %f_sum_sq, %f_val_sq;

    // i += stride
    add.u32 %i, %i, %stride;
    bra LOOP_REDUCE;
END_REDUCE:

    // atomic add to global sum
    mul.lo.u64 %addr, %blockIdx_y, 4;          // c * sizeof(float)
    add.u64 %addr, %rd_sum, %addr;
    atom.global.add.f32 [%addr], %f_sum;

    // atomic add to global sum_sq
    mul.lo.u64 %addr, %blockIdx_y, 4;
    add.u64 %addr, %rd_sum_sq, %addr;
    atom.global.add.f32 [%addr], %f_sum_sq;

    ret;
}

